<script>let searching=false;let adminScanning=false;function found(text){if(searching)return;searching=true;window.location.href=`{{route('admin.student-search')}}?q=${encodeURIComponent(text)}`}const adminQr=new Html5Qrcode('adminReader');function adminStarted(){adminScanning=true;document.getElementById('startAdminScan').hidden=true;document.getElementById('stopAdminScan').hidden=false}function startAdminScanner(){if(adminScanning)return;const facingMode=document.getElementById('adminCameraFacing').value;const config={fps:10,qrbox:{width:210,height:210},disableFlip:facingMode==='environment'};adminQr.start({facingMode},config,found).then(adminStarted).catch(firstError=>Html5Qrcode.getCameras().then(cameras=>{if(!cameras.length)throw firstError;const pattern=facingMode==='environment'?/back|rear|environment|belakang/i:/front|user|depan|facetime/i;const camera=cameras.find(item=>pattern.test(item.label))||(facingMode==='environment'?cameras[cameras.length-1]:cameras[0]);return adminQr.start(camera.id,config,found).then(adminStarted)}).catch(error=>{console.error('Gagal membuka kamera:',error);alert(!window.isSecureContext?'Kamera hanya dapat dibuka melalui HTTPS atau localhost.':'Kamera tidak dapat dibuka. Periksa izin kamera di Safari lalu muat ulang halaman.')}))}function stopAdminScanner(){if(!adminScanning)return Promise.resolve();return adminQr.stop().then(()=>{adminScanning=false;document.getElementById('stopAdminScan').hidden=true})}document.getElementById('startAdminScan').addEventListener('click',startAdminScanner);document.getElementById('adminCameraFacing').addEventListener('change',()=>{if(adminScanning)stopAdminScanner().then(startAdminScanner).catch(()=>{})});document.getElementById('stopAdminScan').addEventListener('click',()=>stopAdminScanner().then(()=>location.reload()).catch(()=>{}));document.getElementById('adminImage').addEventListener('change',e=>{const f=e.target.files?.[0];if(f)adminQr.scanFile(f,true).then(found).catch(()=>{});e.target.value=''})</script>
